import json, os
BASE="/home/hatch/workspace/divination/benchmark/phase3/runs/round79/predictions"
os.makedirs(BASE, exist_ok=True)
def w(cid, pred, basis, conf, trig):
    d={"case_id":cid,"prediction_text":pred,"basis":basis,"confidence":conf,"trigger":trig}
    p=os.path.join(BASE,cid+".json")
    with open(p,"w",encoding="utf-8") as f: json.dump(d,f,ensure_ascii=False,indent=1)
    print(p, os.path.getsize(p))
